   * Reserves a region of the shared drawing buffer for one draw of this size
   * and points the viewport at it. Returns where the draw's bottom-left
   * corner lands, which it adds to its gl_FragCoord-based centre. With part,
   * only that rectangle of the draw (CSS-style, from the top left) is shaded
   * and later replaced; the rest of the surface's canvas keeps its pixels.
   */
  begin: (width: number, height: number, part?: SoapBubbleRect | null) => [number, number];
  /**
   * Queues the last draw for its surface's own canvas; see flush. A context
   * that draws in its surface's canvas has nothing to hand over.
   */
  present: (surface: CanvasRenderingContext2D | null) => void;
  emptyTexture: WebGLTexture;
  /** Present queued surfaces immediately when composed inside another canvas. */
  flush: () => void;
  /**
   * True once the program has linked. A paced context links on the driver's
   * own thread, and its surfaces wait for it instead of the page.
   */
  ready: () => boolean;
  /** Frames handed over that the GPU has not finished drawing yet. */
  inFlight: (now: number) => number;
  /**
   * When the browser took the context away (a GPU reset, the system switching
   * graphics cards, a tab left in the background for long), or 0 while it has
   * it. Until it is given back nothing draws, and every surface keeps the
   * pixels it last showed.
   */
  lostSince: () => number;
  /**
   * Called once the browser gives a lost context back, with the program and
   * every texture made again: whatever was drawn must be drawn again.
   */
  onRestore: (listener: () => void) => () => void;
};

let shared: SoapBubbleContext | null | undefined;
// A lost context the browser has not given back by then (it drops the oldest
// once a page holds too many, and never returns that one) is replaced.
const replaceLostAfter = 3000;

// Every surface over one backdrop asks for its box in the same task; the
// box is read once and forgotten when the task's draws are handed over.
const rects = new Map<Element, DOMRect>();
export function frameRect(element: Element) {
  let rect = rects.get(element);
  if (!rect) rects.set(element, (rect = element.getBoundingClientRect()));
  return rect;
}

export function soapBubbleContext(): SoapBubbleContext | null {
  if (shared === undefined) shared = createSoapBubbleContext(soapBubbleFragment, { paced: true });
  else if (shared) {
    const since = shared.lostSince();
    if (
      since &&
      performance.now() - since > replaceLostAfter &&
      typeof document !== 'undefined' &&
      !document.hidden
    ) {
      const fresh = createSoapBubbleContext(soapBubbleFragment, { paced: true });
      // Surfaces notice the new context on their next draw and draw whole.
      if (fresh) shared = fresh;
    }
  }
  return shared;
}

// In iOS Safari a copy out of the shared buffer reads that buffer back from
// the GPU, which a surface that animates whole (a menu opening) pays on
// every frame. Firefox reads it back once for every surface it is copied
// into, so an idle page of them fell to 30 frames a second there. In both,
// each surface draws in its own canvas with a context of its own instead, so
// nothing is copied.
const userAgent = typeof navigator !== 'undefined' ? navigator.userAgent : '';
const gecko = /\bFirefox\/\d/.test(userAgent);
const ownContexts =
  typeof navigator !== 'undefined' &&
  (/iP(hone|ad|od)/.test(userAgent) ||
    (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1) ||
    gecko);
// WebKit keeps 16 WebGL contexts on a page and fails past that, counting a
// released context until it is collected; Firefox drops the oldest past 16.
// Surfaces take at most 12 of those still alive, leaving the page room for
// its own; any more share the one context as everywhere else.
const ownContextLimit = 12;
const ownContextsInUse = new Map<HTMLCanvasElement, SoapBubbleContext>();
let ownContextsAlive = 0;
const ownContextCollected =
  typeof FinalizationRegistry === 'function'
    ? new FinalizationRegistry<null>(() => {
        ownContextsAlive--;
      })
    : null;

function releaseOwnContext(canvas: HTMLCanvasElement) {
  const context = ownContextsInUse.get(canvas);
  if (!context) return;
  ownContextsInUse.delete(canvas);
  forgetUploads(context.gl);
  context.gl.getExtension('WEBGL_lose_context')?.loseContext();
}

/** Drops a context's backdrop textures, which go with the context. */
function forgetUploads(gl: WebGL2RenderingContext) {
  for (const entry of backdrops.values()) {
    entry.uploads.delete(gl);
    entry.groundUploads.delete(gl);
    for (const view of entry.covered.values()) view.uploads.delete(gl);
  }
}

// Firefox has no parallel compile: making a context there blocks for about
// 45 ms, and a sheet that brings four surfaces froze one frame for 180 ms.
// There at most one own context is made a frame; the rest wait a frame or two.
let frameNumber = 0;
let ownMadeInFrame = -1;

/**
 * The context a surface drawing in canvas should use: its own where that
 * pays and the limit allows, null for the shared one, or 'later' when it is
 * to have its own but not in this frame. A canvas keeps the context it was
 * first given, so a surface mounted on it again (as React does in
 * development) takes that context back.
 */
export function soapBubbleOwnContext(
  canvas: HTMLCanvasElement,
): SoapBubbleContext | null | 'later' {
  if (!ownContexts) return null;
  const existing = ownContextsInUse.get(canvas);
  if (existing) return existing;
  for (const used of ownContextsInUse.keys()) if (!used.isConnected) releaseOwnContext(used);
  if (ownContextsAlive >= ownContextLimit) return null;
  if (gecko && ownMadeInFrame === frameNumber) return 'later';
  const context = createSoapBubbleContext(soapBubbleFragment, { surface: canvas });
  if (!context) return null;
  ownMadeInFrame = frameNumber;
  ownContextsInUse.set(canvas, context);
  ownContextsAlive++;
  ownContextCollected?.register(context.gl, null);
  return context;
}

/** Frees the own context of a surface whose canvas has left the page. */
export function releaseSoapBubbleOwnContext(canvas: HTMLCanvasElement) {
  // React removes the canvas before it runs the effect's cleanup; a canvas
  // still on the page is mounted again.
  window.setTimeout(() => {
    if (!canvas.isConnected) releaseOwnContext(canvas);
  });
}

/** Same Bubble UI optics and resources, with an optional custom outline shader. */
export function createSoapBubbleContext(
  fragmentSource = soapBubbleFragment,
  {
    paced = false,
    surface,
  }: {
    paced?: boolean;
    /** A surface's own canvas, to draw in directly. */
    surface?: HTMLCanvasElement;
  } = {},
): SoapBubbleContext | null {
  // Off screen where possible, so the shared buffer is never composited.
  const canvas: HTMLCanvasElement | OffscreenCanvas =
    surface ??
    (typeof OffscreenCanvas === 'function'
      ? new OffscreenCanvas(1024, 512)
      : Object.assign(document.createElement('canvas'), { width: 1024, height: 512 }));
  const gl = canvas.getContext('webgl2', {
    premultipliedAlpha: true,
    alpha: true,
    antialias: false,
    // The shared context shades every frame's regions afresh, so its buffer
    // need not be kept between frames. In its own canvas, a surface's resting
    // outline stays from the last whole draw.
    preserveDrawingBuffer: !paced || Boolean(surface),
  });
  if (!gl) return null;
  // The driver compiles and links on its own thread while the lookup tables
  // are built here; nothing asks for the result until both are done. Paced,
  // the surfaces then ask each frame whether it is done rather than wait.
  let parallel: KHR_parallel_shader_compile | null = null;
  const compile = (type: number, source: string) => {
    const shader = gl.createShader(type)!;
    gl.shaderSource(shader, source);
    gl.compileShader(shader);
    return shader;
  };
  const u = {} as SoapBubbleContext['u'];
  const set = uniformSetters(gl);
  let program: WebGLProgram;
  let vertex: WebGLShader;
  let fragment: WebGLShader;
  let emptyTexture: WebGLTexture;
  let linked = false;
  let failed = false;
  // Everything the context holds. A lost context loses all of it, and it is
  // made again once the browser gives the context back.
  const build = () => {
    linked = false;
    failed = false;
    // Extensions have to be asked for again once a lost context is back.
    parallel = paced || surface ? gl.getExtension('KHR_parallel_shader_compile') : null;
    program = gl.createProgram()!;
    vertex = compile(gl.VERTEX_SHADER, soapBubbleVertex);
    fragment = compile(gl.FRAGMENT_SHADER, fragmentSource);
    gl.attachShader(program, vertex);
    gl.attachShader(program, fragment);
    gl.linkProgram(program);
    // The film table lives on unit 1 for good; backdrops take unit 0.
    const film = gl.createTexture();
    gl.activeTexture(gl.TEXTURE1);
    gl.bindTexture(gl.TEXTURE_2D, film);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texImage2D(
      gl.TEXTURE_2D,
      0,
      gl.RGBA16F,
      soapBubbleFilmSize[0],
      soapBubbleFilmSize[1],
      0,
      gl.RGBA,
      gl.FLOAT,
      (filmTableData ??= filmTable()),
    );
    // Noise on unit 2.
    const noise = gl.createTexture();
    gl.activeTexture(gl.TEXTURE2);
    gl.bindTexture(gl.TEXTURE_3D, noise);
    gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_3D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    for (const wrap of [gl.TEXTURE_WRAP_S, gl.TEXTURE_WRAP_T, gl.TEXTURE_WRAP_R])
      gl.texParameteri(gl.TEXTURE_3D, wrap, gl.REPEAT);
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 1);
    gl.texImage3D(
      gl.TEXTURE_3D,
      0,
      gl.R8,
      soapBubbleNoiseSize,
      soapBubbleNoiseSize,
      soapBubbleNoiseSize,
      0,
      gl.RED,
      gl.UNSIGNED_BYTE,
      (noiseVolumeData ??= noiseVolume()),
    );
    gl.pixelStorei(gl.UNPACK_ALIGNMENT, 4);
    gl.activeTexture(gl.TEXTURE0);
    if (!parallel) link();

    const quad = gl.createVertexArray();
    gl.bindVertexArray(quad);
    gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    gl.enableVertexAttribArray(0);
    gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);

    emptyTexture = createBackdropTexture(gl);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array(4));
    gl.generateMipmap(gl.TEXTURE_2D);
  };

  // A context can be lost at any time: a GPU reset, the system switching
  // graphics cards, or a tab left in the background for long. Kept (by
  // preventing the default), the browser may give it back, and everything is
  // then made again and drawn again. Until then every surface keeps showing
  // what it last drew instead of going blank.
  let lostSince = 0;
  const restoreListeners = new Set<() => void>();
  const events = canvas as EventTarget;
  events.addEventListener('webglcontextlost', (event) => {
    event.preventDefault();
    lostSince = performance.now();
    linked = false;
    fences.length = 0;
    pending.length = 0;
  });
  events.addEventListener('webglcontextrestored', () => {
    lostSince = 0;
    set.reset();
    forgetUploads(gl);
    used.width = used.height = used.frames = 0;
    build();
    restoreListeners.forEach((listener) => listener());
  });

  const link = () => {
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      const message =
        [vertex, fragment]
          .map((shader) =>
            gl.getShaderParameter(shader, gl.COMPILE_STATUS) ? '' : gl.getShaderInfoLog(shader),
          )
          .find(Boolean) || gl.getProgramInfoLog(program);
      gl.deleteShader(vertex);
      gl.deleteShader(fragment);
      gl.deleteProgram(program);
      throw new Error(message || 'Soap Bubble program failed to link.');
    }
    gl.deleteShader(vertex);
    gl.deleteShader(fragment);
    gl.useProgram(program);
    for (const name of uniformNames) u[name] = gl.getUniformLocation(program, name);
    gl.uniform1i(u.uBackdrop, 0);
    gl.uniform1i(gl.getUniformLocation(program, 'uFilmTable'), 1);
    gl.uniform1i(gl.getUniformLocation(program, 'uNoise'), 2);
    gl.uniform1i(gl.getUniformLocation(program, 'uCovered'), 3);
    gl.uniform1i(gl.getUniformLocation(program, 'uGround'), 4);
    linked = true;
  };
  build();

  const context: SoapBubbleContext = {
    gl,
    canvas,
    u,
    set,
    get emptyTexture() {
      return emptyTexture;
    },
    flush: () => flush(),
    ready() {
      if (lostSince || gl.isContextLost()) return false;
      if (linked) return true;
      if (failed || !gl.getProgramParameter(program, parallel!.COMPLETION_STATUS_KHR)) return false;
      try {
        link();
      } catch {
        failed = true;
      }
      return linked;
    },
    lostSince: () => lostSince,
    onRestore(listener) {
      restoreListeners.add(listener);
      return () => {
        restoreListeners.delete(listener);
      };
    },
    inFlight(now) {
      while (fences.length) {
        const status = gl.isContextLost()
          ? gl.SIGNALED
          : gl.getSyncParameter(fences[0].sync, gl.SYNC_STATUS);
        if (status !== gl.SIGNALED) break;
        const done = fences.shift()!;
        gl.deleteSync(done.sync);
        gpuDone(now - done.at);
      }
      return fences.length;
    },
    begin(width, height, part) {
      if (surface) {
        gl.viewport(0, 0, width, height);
        if (part) {
          gl.enable(gl.SCISSOR_TEST);
          gl.scissor(part.x, height - part.y - part.height, part.width, part.height);
        } else gl.disable(gl.SCISSOR_TEST);
        return [0, 0];
      }
      const rect = part ?? { x: 0, y: 0, width, height };
      const [x, y] = reserve(rect.width, rect.height);
      // The draw is placed so that its part falls on the reserved region.
      const originX = x - rect.x;
      const originY = y - (height - rect.y - rect.height);
      gl.viewport(originX, originY, width, height);
      // The shader writes every pixel it covers, so nothing is cleared.
      if (part) {
        gl.enable(gl.SCISSOR_TEST);
        gl.scissor(x, y, rect.width, rect.height);
      } else gl.disable(gl.SCISSOR_TEST);
      queued = { x, y, width: rect.width, height: rect.height, left: rect.x, top: rect.y };
      return [originX, originY];
    },
    present(target) {
      if (target) pending.push({ target, ...queued });
      if (!flushQueued) {
        flushQueued = true;
        // Every surface drawn in this task shares one hand-over.
        queueMicrotask(flush);
      }
    },
  };

  // The frame's draws are packed side by side into the shared buffer, in
  // shelves from the bottom, and handed to their canvases together: one GPU
  // read-back a frame instead of one per surface.
  type Region = { x: number; y: number; width: number; height: number; left: number; top: number };
  const pending: (Region & { target: CanvasRenderingContext2D })[] = [];
  const atlas = { x: 0, y: 0, shelf: 0, right: 0 };
  // That read-back takes the whole buffer, in Safari at a cost that follows
  // its area rather than the regions drawn: a buffer grown for one menu
  // opening slowed every frame after it. So the buffer is kept to what the
  // frames use, grown to fit the frame that overflowed it and shrunk once
  // the frames of the last two seconds or so all needed far less.
  const used = { width: 0, height: 0, frames: 0 };
  const fit = (width: number, height: number) => {
    const round = (size: number) => Math.min(8192, Math.max(64, Math.ceil(size / 64) * 64));
    if (canvas.width !== round(width)) canvas.width = round(width);
    if (canvas.height !== round(height)) canvas.height = round(height);
  };
  let queued: Region = { x: 0, y: 0, width: 0, height: 0, left: 0, top: 0 };
  let flushQueued = false;
  let staging: HTMLCanvasElement | null = null;
  let stagingContext: CanvasRenderingContext2D | null = null;
  // A paced context marks the end of each frame's draws, to learn when the
  // GPU is through with them.
  const fences: { sync: WebGLSync; at: number }[] = [];
  const reserve = (width: number, height: number): [number, number] => {
    if (atlas.x + width > canvas.width) {
      atlas.x = 0;
      atlas.y += atlas.shelf;
      atlas.shelf = 0;
    }
    if (atlas.y + height > canvas.height || width > canvas.width) {
      // Full: hand over what is drawn, then grow so a frame like this fits,
      // with a quarter to spare. Each growth reallocates the buffer, which
      // costs a long frame; a menu or sheet opening otherwise grows it again
      // for every surface it brings.
      const need = atlas.y + height;
      flush();
      fit(Math.max(canvas.width, width), Math.max(canvas.height, need * 1.25));
    }
    const at: [number, number] = [atlas.x, atlas.y];
    atlas.x += width;
    atlas.shelf = Math.max(atlas.shelf, height);
    atlas.right = Math.max(atlas.right, atlas.x);
    return at;
  };
  const flush = () => {
    flushQueued = false;
    rects.clear();
    const usedWidth = atlas.right;
    const usedHeight = atlas.y + atlas.shelf;
    atlas.x = 0;
    atlas.y = 0;
    atlas.shelf = 0;
    atlas.right = 0;
    if (!pending.length) return;
    // A lost context draws nothing: the surfaces keep what they show.
    if (gl.isContextLost()) {
      pending.length = 0;
      return;
    }
    if (paced && fences.length < 4) {
      const sync = gl.fenceSync(gl.SYNC_GPU_COMMANDS_COMPLETE, 0);
      if (sync) fences.push({ sync, at: performance.now() });
    }
    // Copied straight from the buffer. Through transferToImageBitmap, Safari
    // reads every copy back from the GPU while painting, and the page falls
    // to a few frames a second. Firefox reads the buffer back for every copy
    // taken from it, so there (with more surfaces than own contexts) it is
    // read back once into a canvas of its own and the copies come from that.
    let source: HTMLCanvasElement | OffscreenCanvas = canvas;
    let bottom = canvas.height;
    if (gecko && pending.length > 1 && typeof document !== 'undefined') {
      staging ??= document.createElement('canvas');
      if (staging.width !== canvas.width) staging.width = canvas.width;
      if (staging.height !== canvas.height) staging.height = canvas.height;
      stagingContext ??= staging.getContext('2d');
      if (stagingContext) {
        stagingContext.clearRect(0, 0, usedWidth, usedHeight);
        stagingContext.drawImage(
          canvas,
          0,
          canvas.height - usedHeight,
          usedWidth,
          usedHeight,
          0,
          0,
          usedWidth,
          usedHeight,
        );
        source = staging;
        bottom = usedHeight;
      }
    }
    for (const { target, x, y, width, height, left, top } of pending) {
      target.clearRect(left, top, width, height);
      // WebGL rows start at the bottom of the buffer.
      target.drawImage(source, x, bottom - y - height, width, height, left, top, width, height);
    }
    pending.length = 0;
    used.width = Math.max(used.width, usedWidth);
    used.height = Math.max(used.height, usedHeight);
    if (++used.frames < 60) return;
    if (used.width * used.height * 2 < canvas.width * canvas.height) fit(used.width, used.height);
    used.width = 0;
    used.height = 0;
    used.frames = 0;
  };
  return context;
}

/**
 * The backdrop's last capture as a texture of the context gl, uploaded once
 * per capture and context.
 */
export function backdropTexture(gl: WebGL2RenderingContext, backdrop: SoapBubbleBackdrop) {
  const entry = backdrop as BackdropEntry;
  return uploaded(gl, entry.uploads, entry.source, entry.version, true);
}

/**
 * What the backdrop looks like with its bubbles in it, for a surface that
 * shows the bubbles it covers: null until that is captured. A floating
 * surface (in a group, as a menu's panel) passes null; one laid among the
 * others passes its own element, which that view then leaves out so the
 * surface does not see itself.
 */
export function coveredTexture(
  gl: WebGL2RenderingContext,
  backdrop: SoapBubbleBackdrop,
  self: CoveredKey,
) {
  const entry = backdrop as BackdropEntry;
  const view = entry.covered.get(self);
  if (!view?.canvas || !entry.ground) return null;
  // Panels can soften covered controls just like the ordinary backdrop.
  // Built only when the settled capture changes, never on animation frames.
  return {
    covered: uploaded(gl, view.uploads, view.canvas, view.version, true, true),
    ground: uploaded(gl, entry.groundUploads, entry.ground, entry.groundVersion, true),
  };
}

/**
 * Counts the surfaces that show what they cover, per view, and how many of
 * them are on screen: a view kept for a hidden surface (a closed menu's
 * panel) is refreshed only once one shows it again.
 */
export function wantCoveredBackdrop(
  backdrop: SoapBubbleBackdrop,
  self: CoveredKey,
  want: number,
  shown: number,
) {
  const entry = backdrop as BackdropEntry;
  let view = entry.covered.get(self);
  if (!view) {
    if (want <= 0) return;
    entry.covered.set(
      self,
      (view = { canvas: null, version: 0, uploads: new Map(), wanted: 0, shown: 0 }),
    );
    compose(entry, self, view);
  }
  view.wanted += want;
  view.shown += shown;
  if (view.wanted > 0) return scheduleLayer(entry);
  deleteUploads(view.uploads);
  entry.covered.delete(self);
}

function deleteUploads(uploads: Uploads) {
  for (const [gl, upload] of uploads) if (!gl.isContextLost()) gl.deleteTexture(upload.texture);
}

type Uploads = Map<WebGL2RenderingContext, { texture: WebGLTexture; version: number }>;

function uploaded(
  gl: WebGL2RenderingContext,
  uploads: Uploads,
  source: TexImageSource | null,
  version: number,
  mipmaps: boolean,
  premultiplied = false,
) {
  let upload = uploads.get(gl);
  if (!upload)
    uploads.set(gl, (upload = { texture: createBackdropTexture(gl, mipmaps), version: 0 }));
  if (source && upload.version !== version) {
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, upload.texture);
    gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, premultiplied);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, source);
    gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
    if (mipmaps) gl.generateMipmap(gl.TEXTURE_2D);
    upload.version = version;
  }
  return upload.texture;
}

function createBackdropTexture(gl: WebGL2RenderingContext, mipmaps = true) {
  const texture = gl.createTexture()!;
  gl.activeTexture(gl.TEXTURE0);
  gl.bindTexture(gl.TEXTURE_2D, texture);
  gl.texParameteri(
    gl.TEXTURE_2D,
    gl.TEXTURE_MIN_FILTER,
    mipmaps ? gl.LINEAR_MIPMAP_LINEAR : gl.LINEAR,
  );
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
  return texture;
}

/**
 * Which view of the backdrop a surface shows: a surface over other bubbles has
 * its own, one in a group shares null, and 'page' is for one over the page alone.
 */
export type CoveredKey = Element | null | 'page';

export type SoapBubbleBackdrop = {
  element: HTMLElement;
  /** Texel size, or null until the first capture lands. */
  size: [number, number] | null;
  failed: boolean;
};

type BackdropEntry = SoapBubbleBackdrop & {
  /** The last capture, counted so each context uploads it once. */
  source: TexImageSource | null;
  version: number;
  uploads: Uploads;
  /**
   * What lies on the backdrop: its text and images, and its bubbles (groups
   * left out, and the surface a view is for), over nothing, so that a view's
   * alpha says where something lies. For surfaces that show what they cover,
   * which is every one with a body to see through. Every view is put
   * together from one capture of the bubbles' content, taken only while a
   * view is wanted, and then only when the page has settled after a change.
   */
  covered: Map<CoveredKey, CoveredView>;
  /** The backdrop with nothing on it, which surfaces see past what they cover. */
  ground: TexImageSource | null;
  groundVersion: number;
  groundUploads: Uploads;
  layer: {
    canvas: HTMLCanvasElement | null;
    /** The same without any surface, for the 'page' view. */
    page: HTMLCanvasElement | null;
    /**
     * Which parts the page changed under since they were captured: its text,
     * images, size or scroll show in every one.
     */
    stale: { ground: boolean; page: boolean; bubbles: boolean };
    /**
     * Bubbles whose own content changed since the bubbles were captured. They
     * are not in the 'page' view, and only matter to a view whose surfaces
     * lie over them: a button pressed elsewhere costs no capture.
     */
    changed: Set<Element>;
    /**
     * What attributes and text inside bubbles were when the bubbles were
     * captured, for those changed since: a press that plays out and settles
     * where it started has changed nothing.
     */
    was: Map<Node, Map<string, string | null>>;
    /** Where each bubble was on the backdrop when the bubbles were captured. */
    boxes: Map<Element, DOMRect>;
    capturing: boolean;
    /** Asked for while capturing, so looked at again once done. */
    again: boolean;
    timer: number;
  };
  fontEmbedCSS: Promise<string> | null;
  listeners: Set<() => void>;
  capturing: boolean;
  dirty: boolean;
  timer: number;
  mutations: MutationObserver;
  scrolled: (event: Event) => void;
  /** What has scrolled inside the element: a snapshot starts it all at the top. */
  scrollers: Set<Element>;
  resize: ResizeObserver;
};

type CoveredView = {
  canvas: HTMLCanvasElement | null;
  version: number;
  uploads: Uploads;
  wanted: number;
  shown: number;
};

const backdrops = new Map<HTMLElement, BackdropEntry>();

// Changes inside any surface (labels, moving thumbs, ready flags) are left
// out of the snapshot anyway and must not trigger another capture. A group
// (a menu, a burst) holds only surfaces, so it is left out the same way.
const bubbleSelector = '[data-soap-bubble], [data-soap-bubble-group]';
const insideSurface = (node: Node) =>
  (node instanceof Element ? node : node.parentElement)?.closest(bubbleSelector) != null;
const groupSelector = '[data-soap-bubble-group]';
const insideGroup = (node: Node) =>
  (node instanceof Element ? node : node.parentElement)?.closest(groupSelector) != null;
const surfaceOf = (node: Node) =>
  (node instanceof Element ? node : node.parentElement)?.closest('[data-soap-bubble]') ?? null;
const scrollAttribute = 'data-soap-bubble-scroll';

/** A snapshot clones the page without its scroll offsets, so its children carry them instead. */
function scrollOffsets(entry: BackdropEntry) {
  let css = '';
  let index = 0;
  for (const scroller of entry.scrollers) {
    if (!scroller.isConnected) {
      entry.scrollers.delete(scroller);
      continue;
    }
    const id = String(index++);
    if (scroller.getAttribute(scrollAttribute) !== id) scroller.setAttribute(scrollAttribute, id);
    css += `[${scrollAttribute}="${id}"] > * { translate: ${-scroller.scrollLeft}px ${-scroller.scrollTop}px !important; }\n`;
  }
  return css;
}

/**
 * One rasterised copy of a backdrop element, shared by every surface over it
 * and refreshed whenever the element changes. Returns a release function.
 */
export function subscribeBackdrop(
  element: HTMLElement,
  onChange: (backdrop: SoapBubbleBackdrop) => void,
): () => void {
  let entry = backdrops.get(element);
  if (!entry) {
    const created: BackdropEntry = {
      element,
      source: null,
      version: 0,
      uploads: new Map(),
      covered: new Map(),
      ground: null,
      groundVersion: 0,
      groundUploads: new Map(),
      layer: {
        canvas: null,
        page: null,
        stale: { ground: true, page: true, bubbles: true },
        changed: new Set(),
        was: new Map(),
        boxes: new Map(),
        capturing: false,
        again: false,
        timer: 0,
      },
      fontEmbedCSS: null,
      size: null,
      failed: false,
      listeners: new Set(),
      capturing: false,
      dirty: false,
      timer: 0,
      mutations: new MutationObserver((all) => {
        const records = all.filter((record) => record.attributeName !== scrollAttribute);
        if (records.some((record) => !insideSurface(record.target))) schedule(created);
        // The bubbles are in the covered views; a menu opening is not, nor the
        // flags surfaces set on their canvases. A change inside a bubble is
        // only seen by the surfaces over it.
        let page = false;
        let bubbles = false;
        for (const { target, type, attributeName, oldValue } of records) {
          if (insideGroup(target) || attributeName === 'data-backdrop') continue;
          const bubble = surfaceOf(target);
          if (!bubble) {
            page = true;
            continue;
          }
          bubbles = true;
          if (type === 'childList') {
            created.layer.changed.add(bubble);
            continue;
          }
          let values = created.layer.was.get(target);
          if (!values) created.layer.was.set(target, (values = new Map()));
          if (!values.has(attributeName ?? '')) values.set(attributeName ?? '', oldValue);
        }
        if (page) staleCovered(created);
        else if (bubbles) scheduleLayer(created);
      }),
      resize: new ResizeObserver(() => {
        schedule(created);
        staleCovered(created);
      }),
      // Scrolling moves what is seen through the film without a mutation.
      // A menu's list scrolling is in no snapshot; a bubble's own content
      // scrolling is only in the bubbles' view.
      scrolled: (event) => {
        const { target } = event;
        if (target instanceof Element) {
          if (insideGroup(target)) return;
          created.scrollers.add(target);
          const bubble = surfaceOf(target);
          if (bubble) {
            created.layer.changed.add(bubble);
            scheduleLayer(created);
            return;
          }
        }
        schedule(created);
        staleCovered(created);
      },
      scrollers: new Set(),
    };
    element.addEventListener('scroll', created.scrolled, { capture: true, passive: true });
    created.mutations.observe(element, {
      subtree: true,
      childList: true,
      characterData: true,
      attributes: true,
      attributeOldValue: true,
      characterDataOldValue: true,
    });
    created.resize.observe(element);
    backdrops.set(element, created);
    entry = created;
    void capture(created);
  }
  const current = entry;
  const listener = () => onChange(current);
  current.listeners.add(listener);
  if (current.size || current.failed) listener();
  return () => {
    current.listeners.delete(listener);
    if (current.listeners.size) return;
    window.clearTimeout(current.timer);
    current.mutations.disconnect();
    current.resize.disconnect();
    element.removeEventListener('scroll', current.scrolled, { capture: true });
    deleteUploads(current.uploads);
    deleteUploads(current.groundUploads);
    window.clearTimeout(current.layer.timer);
    for (const view of current.covered.values()) deleteUploads(view.uploads);
    backdrops.delete(element);
  };
}

function schedule(entry: BackdropEntry) {
  window.clearTimeout(entry.timer);
  entry.timer = window.setTimeout(() => void capture(entry), 180);
}

async function capture(entry: BackdropEntry) {
  if (entry.capturing) {
    entry.dirty = true;
    return;
  }
  entry.capturing = true;
  entry.dirty = false;
  const { element } = entry;
  try {
    const rect = element.getBoundingClientRect();
    if (rect.width < 1 || rect.height < 1) throw new Error('Empty backdrop');
    let source: HTMLImageElement | HTMLCanvasElement;
    if (element instanceof HTMLImageElement) {
      await element.decode();
      source = element;
    } else if (element instanceof HTMLCanvasElement) {
      source = element;
    } else {
      await document.fonts?.ready;
      const { toCanvas } = await import('html-to-image');
      source = await toCanvas(element, {
        width: rect.width,
        height: rect.height,
        pixelRatio: Math.min(2, window.devicePixelRatio || 1),
        includeQueryParams: true,
        // Hide the paint, not the boxes: removing an in-flow control moves
        // every sibling below it in the snapshot.
        fontEmbedCSS: `${await fontEmbedCSS(entry)}\n${scrollOffsets(entry)}${bubbleSelector}, [data-soap-bubble] *, [data-soap-bubble-group] * { visibility: hidden !important; }`,
        // A positioned backdrop is rasterised in its own coordinate space.
        // Its page offset must not become an offset inside its texture too.
        style: {
          transform: 'none',
          position: 'relative',
          left: '0',
          top: '0',
          right: 'auto',
          bottom: 'auto',
          margin: '0',
        },
        filter: (node) => !(node instanceof Element && node.localName === 'canvas'),
      });
    }
    if (backdrops.get(element) !== entry) return;
    entry.source = source;
    entry.version++;
    entry.size =
      source instanceof HTMLImageElement
        ? [source.naturalWidth, source.naturalHeight]
        : [source.width, source.height];
    entry.failed = false;
    staleCovered(entry);
  } catch {
    entry.failed = !entry.size;
  } finally {
    entry.capturing = false;
    entry.listeners.forEach((listener) => listener());
    if (entry.dirty && backdrops.get(element) === entry) schedule(entry);
  }
}

// The page's fonts, inlined once per backdrop rather than on every capture.
function fontEmbedCSS(entry: BackdropEntry) {
  entry.fontEmbedCSS ??= import('html-to-image')
    .then(({ getFontEmbedCSS }) => getFontEmbedCSS(entry.element))
    .catch(() => '');
  return entry.fontEmbedCSS;
}

function staleCovered(entry: BackdropEntry) {
  const { stale } = entry.layer;
  stale.ground = stale.page = stale.bubbles = true;
  scheduleLayer(entry);
}

// Each part of the covered views costs a rasterisation, so it waits for the
// page to settle (a slider being dragged, a theme switching) and is skipped
// while no surface that shows it would see the change.
function scheduleLayer(entry: BackdropEntry) {
  const { layer } = entry;
  if (layer.capturing) {
    layer.again = true;
    return;
  }
  const due = layerDue(entry, false);
  if (!entry.source || (!due.page && !due.bubbles)) return;
  window.clearTimeout(layer.timer);
  layer.timer = window.setTimeout(() => void captureLayer(entry), 700);
}

/**
 * Which parts of the covered views to capture again: the page's for a 'page'
 * view, the bubbles' for any other. A view not made yet needs its part
 * whatever happened; once made, it is only refreshed while a surface shows
 * it, and for a bubble that changed, only if that surface lies over it. That
 * last test is left until the capture is due (exact), when a menu's panel has
 * finished opening.
 */
function layerDue(entry: BackdropEntry, exact: boolean) {
  const { layer } = entry;
  const due = { page: false, bubbles: false };
  let changed: Set<Element> | undefined;
  for (const [key, view] of entry.covered) {
    if (key === 'page') {
      due.page ||= !view.canvas || (view.shown > 0 && layer.stale.page);
      continue;
    }
    if (due.bubbles || (view.canvas && view.shown <= 0)) continue;
    if (!view.canvas || layer.stale.bubbles) due.bubbles = true;
    else if (layer.changed.size || layer.was.size)
      due.bubbles = !exact || seesChange(entry, key, (changed ??= changedBubbles(layer)));
  }
  return due;
}

// The bubbles whose content is not what was captured: one that gained or lost
// a node, or whose attributes or text differ from then.
function changedBubbles(layer: BackdropEntry['layer']) {
  const changed = new Set(layer.changed);
  for (const [node, values] of layer.was) {
    const bubble = node.isConnected ? surfaceOf(node) : null;
    if (!bubble || changed.has(bubble)) continue;
    for (const [name, value] of values) {
      const now = name ? (node as Element).getAttribute(name) : (node as CharacterData).data;
      if (now === value) continue;
      changed.add(bubble);
      break;
    }
  }
  return changed;
}

// How far past its box a surface sees what it covers: its lens bends in
// what lies just outside.
const lensReach = 16;

// Whether the surfaces showing a view (one laid among the others, or every
// floating one) lie over a bubble that changed, where it is now or was when
// the bubbles were captured. A surface's own changes are left out of its view.
function seesChange(entry: BackdropEntry, key: Element | null, changed: Set<Element>) {
  if (!changed.size) return false;
  const { element, layer } = entry;
  const origin = element.getBoundingClientRect();
  const areas: DOMRect[] = [];
  const surfaces = key ? [key] : element.querySelectorAll(`${groupSelector} [data-soap-bubble]`);
  for (const surface of surfaces) {
    const box = onBackdrop(surface, origin);
    // A closed menu's panel takes no room and sees nothing.
    if (box.width > 0 && box.height > 0)
      areas.push(
        new DOMRect(
          box.x - lensReach,
          box.y - lensReach,
          box.width + 2 * lensReach,
          box.height + 2 * lensReach,
        ),
      );
  }
  for (const bubble of changed) {
    if (key && (key.contains(bubble) || bubble.contains(key))) continue;
    const then = layer.boxes.get(bubble);
    const now = bubble.isConnected ? onBackdrop(bubble, origin) : undefined;
    if (areas.some((area) => overlaps(area, then) || overlaps(area, now))) return true;
  }
  return false;
}

// An element's box from the backdrop's corner, which holds while the page
// around the backdrop scrolls.
function onBackdrop(element: Element, origin: DOMRect) {
  const box = element.getBoundingClientRect();
  return new DOMRect(box.x - origin.x, box.y - origin.y, box.width, box.height);
}

function overlaps(area: DOMRect, box: DOMRect | undefined) {
  return (
    box != null &&
    box.width > 0 &&
    box.height > 0 &&
    area.left < box.right &&
    box.left < area.right &&
    area.top < box.bottom &&
    box.top < area.bottom
  );
}

async function captureLayer(entry: BackdropEntry) {
  const { element, layer } = entry;
  if (layer.capturing || !entry.source) return;
  const due = layerDue(entry, true);
  if (!due.page && !due.bubbles) return;
  layer.capturing = true;
  const withGround = layer.stale.ground || !entry.ground;
  layer.stale.ground = false;
  if (due.page) layer.stale.page = false;
  if (due.bubbles) {
    layer.stale.bubbles = false;
    layer.changed.clear();
    layer.was.clear();
  }
  try {
    const rect = element.getBoundingClientRect();
    if (rect.width < 1 || rect.height < 1) return;
    let canvas: HTMLCanvasElement | null = null;
    let page: HTMLCanvasElement | null = null;
    let ground: TexImageSource | null = withGround ? entry.source : null;
    const boxes = new Map<Element, DOMRect>();
    if (due.bubbles)
      for (const bubble of element.querySelectorAll('[data-soap-bubble]'))
        if (!insideGroup(bubble)) boxes.set(bubble, onBackdrop(bubble, rect));
    if (element instanceof HTMLImageElement || element instanceof HTMLCanvasElement) {
      if (due.bubbles)
        canvas = Object.assign(document.createElement('canvas'), {
          width: entry.size![0],
          height: entry.size![1],
        });
    } else {
      // Everything stays where it is laid out (leaving a surface out would
      // let the rest close up); only the films, drawn apart, are skipped.
      // At the backdrop's own scale, so the page matches it pixel for pixel.
      const { toCanvas } = await import('html-to-image');
      const snapshot = {
        transform: 'none',
        position: 'relative',
        left: '0',
        top: '0',
        right: 'auto',
        bottom: 'auto',
        margin: '0',
      };
      // The ground has no text: no fonts to inline.
      if (withGround)
        ground = await toCanvas(element, {
          width: rect.width,
          height: rect.height,
          pixelRatio: Math.min(2, window.devicePixelRatio || 1),
          style: snapshot,
          filter: () => false,
          skipFonts: true,
        });
      const content = (hidden: string) =>
        fontEmbedCSS(entry).then((fonts) =>
          toCanvas(element, {
            width: rect.width,
            height: rect.height,
            pixelRatio: Math.min(2, window.devicePixelRatio || 1),
            includeQueryParams: true,
            fontEmbedCSS: `${fonts}\n${scrollOffsets(entry)}${hidden}`,
            style: { ...snapshot, background: 'transparent' },
            filter: (node) => !(node instanceof Element && node.localName === 'canvas'),
          }),
        );
      if (due.page)
        page = await content(
          `${bubbleSelector}, [data-soap-bubble] *, [data-soap-bubble-group] * { visibility: hidden !important; }`,
        );
      // Groups are never part of a covered view. Hide their paint in the
      // snapshot while preserving layout: erasing at their live position
      // afterwards can leave a ghost if they move during rasterisation.
      if (due.bubbles)
        canvas = await content(
          `${groupSelector}, ${groupSelector} * { visibility: hidden !important; }`,
        );
    }
    if (backdrops.get(element) !== entry) return;
    if (ground) {
      entry.ground = ground;
      entry.groundVersion++;
    }
    if (page) layer.page = page;
    if (canvas) {
      layer.canvas = canvas;
      layer.boxes = boxes;
    }
    // Only the views whose part was captured again are put together again.
    for (const [self, view] of entry.covered)
      if (self === 'page' ? page : canvas) compose(entry, self, view);
    entry.listeners.forEach((listener) => listener());
  } catch {
    // Without it, surfaces show the backdrop alone.
  } finally {
    layer.capturing = false;
    if (layer.again) {
      layer.again = false;
      scheduleLayer(entry);
    }
  }
}

// One view from the content layer: groups were hidden during capture; erase
// the surface it is for, then draw the other bubbles' films underneath. A
// surface over the page alone has none to see: its view is the layer without any.
function compose(entry: BackdropEntry, self: CoveredKey, view: CoveredView) {
  const { element, layer } = entry;
  if (self === 'page') {
    if (layer.page) {
      view.canvas = layer.page;
      view.version++;
    }
    return;
  }
  if (!layer.canvas || !entry.source) return;
  const rect = element.getBoundingClientRect();
  const scale = layer.canvas.width / Math.max(1, rect.width);
  const canvas = Object.assign(document.createElement('canvas'), {
    width: layer.canvas.width,
    height: layer.canvas.height,
  });
  const context = canvas.getContext('2d');
  if (!context) return;
  context.drawImage(layer.canvas, 0, 0);
  const leftOut = [...element.querySelectorAll(groupSelector), ...(self ? [self] : [])];
  if (self && !insideGroup(self)) eraseContent(context, self, rect, scale);
  context.globalCompositeOperation = 'destination-over';
  for (const film of element.querySelectorAll<HTMLCanvasElement>('[data-soap-bubble] canvas')) {
    if (!film.width || leftOut.some((root) => root.contains(film))) continue;
    const box = film.getBoundingClientRect();
    context.drawImage(
      film,
      (box.left - rect.left) * scale,
      (box.top - rect.top) * scale,
      box.width * scale,
      box.height * scale,
    );
  }
  view.canvas = canvas;
  view.version++;
}

// Clears what a surface draws itself, its text and icons, from the layer.
function eraseContent(
  context: CanvasRenderingContext2D,
  root: Element,
  origin: DOMRect,
  scale: number,
) {
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  const range = document.createRange();
  for (let node: Node | null = walker.currentNode; node; node = walker.nextNode()) {
    let boxes: Iterable<DOMRect>;
    if (node.nodeType === Node.TEXT_NODE) {
      if (!node.textContent?.trim()) continue;
      range.selectNodeContents(node);
      boxes = range.getClientRects();
    } else if (node instanceof SVGSVGElement || node instanceof HTMLImageElement) {
      boxes = [node.getBoundingClientRect()];
    } else continue;
    for (const box of boxes)
      context.clearRect(
        (box.left - origin.left) * scale - 1,
        (box.top - origin.top) * scale - 1,
        box.width * scale + 2,
        box.height * scale + 2,
      );
  }
}

// One animation frame drives every surface on the page, instead of one
// requestAnimationFrame loop each.
let frameTasks = new Set<(now: number) => void>();
let frameHandle = 0;

export function requestSoapBubbleFrame(task: (now: number) => void) {
  frameTasks.add(task);
  if (!frameHandle) frameHandle = requestAnimationFrame(runFrame);
}

export function cancelSoapBubbleFrame(task: (now: number) => void) {
  frameTasks.delete(task);
}

let runningTasks = new Set<(now: number) => void>();

// One clock for the film's 20 frames a second, shared by every surface. Its drift
// is slow enough not to miss the rest, and it waits while anything scrolls: the
// page's own motion is what the eye is following then.
const filmInterval = 49;
const scrollHold = 150;
let filmAt = 0;
let filmFrame = false;
let scrollingUntil = 0;
export const isFilmFrame = () => filmFrame;
if (typeof window !== 'undefined')
  window.addEventListener(
    'scroll',
    () => {
      scrollingUntil = performance.now() + scrollHold;
    },
    { capture: true, passive: true },
  );

// The GPU's pace. A frame is held back while two earlier ones are still
// being drawn, so a slow GPU never queues work ahead of the page's own
// scrolling and compositing. Should it stay behind, every surface is drawn
// with fewer pixels; a GPU that keeps up never sees a difference.
const resolutionLevels = [1, 0.8, 0.65, 0.5];
let resolutionLevel = 0;
const resolutionListeners = new Set<() => void>();
/** Share of each surface's pixel density the GPU can afford. */
export const soapBubbleResolution = () => resolutionLevels[resolutionLevel];
export function onSoapBubbleResolution(listener: () => void) {
  resolutionListeners.add(listener);
  return () => {
    resolutionListeners.delete(listener);
  };
}

const latencies: number[] = [];
let paceFrom = 0;
let paceLast = 0;
let paceHeld = 0;
let paceFrames = 0;
let slowSpells = 0;
// Time from handing a frame over to its last pixel, as seen from the next
// animation frame.
function gpuDone(latency: number) {
  latencies.push(latency);
}

function pace(now: number, held: boolean) {
  // A gap (a hidden tab, nothing moving, a long task) starts afresh.
  if (now - paceLast > 250) {
    paceFrom = now;
    paceHeld = 0;
    paceFrames = 0;
    latencies.length = 0;
  }
  paceLast = now;
  paceFrames++;
  if (held) paceHeld++;
  if (now - paceFrom < 1000) return;
  // Slow: most frames took the GPU over two display frames, or a third of
  // the animation frames had to wait for it.
  latencies.sort((a, b) => a - b);
  const typical = latencies.length >= 8 ? latencies[latencies.length >> 1] : 0;
  const slow = typical > 34 || paceHeld * 3 > paceFrames;
  slowSpells = slow ? slowSpells + 1 : 0;
  paceFrom = now;
  paceHeld = 0;
  paceFrames = 0;
  latencies.length = 0;
  // Two slow seconds in a row, never a single hitch.
  if (slowSpells >= 2 && resolutionLevel < resolutionLevels.length - 1) {
    slowSpells = 0;
    resolutionLevel++;
    resolutionListeners.forEach((listener) => listener());
  }
}

function runFrame(now: number) {
  frameHandle = 0;
  frameNumber++;
  const held = (shared?.inFlight(now) ?? 0) >= 2;
  if (shared) pace(now, held);
  if (held) {
    // Everything waits a frame; the tasks stay queued.
    frameHandle = requestAnimationFrame(runFrame);
    return;
  }
  filmFrame = now - filmAt >= filmInterval && now >= scrollingUntil;
  if (filmFrame) filmAt = now;
  // Swap the sets instead of copying: tasks queued while running wait for
  // the next frame.
  const tasks = frameTasks;
  frameTasks = runningTasks;
  runningTasks = tasks;
  for (const task of tasks) task(now);
  tasks.clear();
}

